fn replace_ref(cwd: &Path, record: &str, name: &str, replacement: &str) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(record).unwrap()).unwrap()
    else {
        panic!("activation record must be a value map")
    };
    entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1 = Value::Ref(replacement.to_owned());
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

fn assert_resume_rejected_without_disclosure(cwd: &Path, record: &str) {
    let output = support::run(
        cwd,
        [
            OsString::from("program"),
            OsString::from("module"),
            OsString::from("runtime"),
            OsString::from("--resume-record"),
            OsString::from(record),
            OsString::from("--slot"),
            OsString::from(SLOT),
            OsString::from("--authorization"),
            OsString::from(AUTHORITY),
            OsString::from("--format"),
            OsString::from("json"),
        ],
    );
    assert!(!output.status.success());
    let raw = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(!raw.contains(PRIVATE_SENTINEL));
    assert!(!raw.contains("foreign-process/runtime"));
}

fn field<'a>(entries: &'a [(Value, Value)], name: &str) -> &'a Value {
    entries
        .iter()
        .find_map(|(key, value)| (key == &Value::Text(name.to_owned())).then_some(value))
        .unwrap()
}

